import React, { useRef, useState } from 'react';
import emailjs from '@emailjs/browser';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import './Contact.css';

function Contact() {

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');

  const handleEmailChange = (evt) => {
    setEmail(evt.target.value);
  }

  const handleNameChange = (evt) => {
    setName(evt.target.value);
  }

  const handleMessageChange = (evt) => {
    setMessage(evt.target.value);
  }

  const form = useRef();

  const sendEmail = (e) => {
    e.preventDefault();

    emailjs
      .sendForm('service_gt0vhwi', 'template_41osrfo', form.current, {
        publicKey: '14Elam1xP57BudDQF',
      })
      .then(
        () => {
          toast('Message Sent!');
          console.log('SUCCESS!');
          form.current.reset();
        },
        (error) => {
          toast('Oops! There was an error!');
          console.log('FAILED...', error.text);
        },
      );
  };

  const enabled =
    email !== '' &&
    name !== '' && message !== '';

  return (
    <div className="Contact">
      <h1>Contact</h1>
      <h3>Please feel free to reach out for any inquiries</h3>
      <ToastContainer position='top-center' />
      <form ref={form} onSubmit={sendEmail}>
        <label>Name<span>*</span></label>
        <input type="text" name="user_name" value={name} onChange={handleNameChange} />
        <label>Email Address<span>*</span></label>
        <input type="email" name="user_contact" value={email} onChange={handleEmailChange} />
        <label>Location</label>
        <input type="text" name="user_location" />
        <label>Message<span>*</span></label>
        <textarea name="message" value={message} onChange={handleMessageChange} />
        <input type="submit" value="Send" disabled={!enabled} />
      </form>
    </div>
  );
}

export default Contact;
